/* Project map -- interactive viewer.
 *
 * The model (nodes, edges, pre-computed scenes) is generated by
 * scripts/project_map/build.py. This file only draws it and handles the
 * interaction: pan/zoom, drill-down, selection, highlighting, search, deep
 * links, theme and export. No dependencies.
 *
 * Deep links:  #view=hierarchy|tlm|classes & scene=<id> & node=<id> [& theme=dark]
 * API:         window.projectMap = { sceneIds(), show(id), select(id), exportSvgString(), setTheme(t) }
 */
(function () {
  "use strict";

  const SVG_NS = "http://www.w3.org/2000/svg";
  const VIEW_LABEL = { hierarchy: "Hierarchy", tlm: "TLM / data flow", classes: "Classes (UML)" };

  // ------------------------------------------------------------------ helpers
  function el(tag, attrs, children) {
    const e = document.createElement(tag);
    if (attrs) for (const k in attrs) {
      if (k === "class") e.className = attrs[k];
      else if (k === "html") e.innerHTML = attrs[k];
      else if (k.startsWith("on")) e.addEventListener(k.slice(2), attrs[k]);
      else e.setAttribute(k, attrs[k]);
    }
    (children || []).forEach(c => e.append(c));
    return e;
  }
  function svg(tag, attrs) {
    const e = document.createElementNS(SVG_NS, tag);
    if (attrs) for (const k in attrs) e.setAttribute(k, attrs[k]);
    return e;
  }
  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }
  function md(text) {
    // tiny markdown: paragraphs, `code`, **bold**
    if (!text) return "";
    return text.trim().split(/\n\s*\n/).map(p =>
      "<p>" + esc(p).replace(/`([^`]+)`/g, "<code>$1</code>").replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>") + "</p>").join("");
  }
  function trunc(s, n) { s = String(s || ""); return s.length > n ? s.slice(0, n - 1) + "…" : s; }

  // A small SystemVerilog highlighter: comments, strings, numbers, macros, system tasks, keywords.
  const SV_KW = new Set(("module endmodule interface endinterface class endclass extends virtual function endfunction task endtask " +
    "package endpackage import export typedef enum struct union logic bit byte int integer shortint longint real string time " +
    "input output inout wire reg parameter localparam rand randc constraint if else case casez casex endcase default for foreach " +
    "while repeat forever do begin end fork join join_any join_none return break continue new null this super static automatic " +
    "local protected pure extern const ref void initial always always_ff always_comb always_latch assign posedge negedge or and " +
    "not xor generate endgenerate genvar covergroup endgroup coverpoint cross bins ignore_bins illegal_bins with inside dist solve " +
    "before wait disable assert property endproperty sequence endsequence unique priority var type signed unsigned " +
    "modport clocking endclocking program endprogram").split(" "));
  const SV_RE = /(\/\/[^\n]*|\/\*[\s\S]*?\*\/)|("(?:[^"\\]|\\.)*")|(`\w+)|(\$\w+)|(\b\d+'[sS]?[bodhBODH][0-9a-fA-F_xzXZ?]+\b|\b\d[\d_]*\b)|(\b[A-Za-z_]\w*\b)/g;
  function highlightSV(code) {
    return code.replace(SV_RE, (m, com, str, mac, sys, num, id) => {
      if (com) return `<span class="c">${com}</span>`;
      if (str) return `<span class="s">${str}</span>`;
      if (mac) return `<span class="m">${mac}</span>`;
      if (sys) return `<span class="y">${sys}</span>`;
      if (num) return `<span class="n">${num}</span>`;
      if (id) return SV_KW.has(id) ? `<span class="k">${id}</span>` : (/^uvm_/.test(id) ? `<span class="u">${id}</span>` : id);
      return m;
    });
  }

  // ------------------------------------------------------------------ app
  class ProjectMap {
    constructor(root, model, opts) {
      this.root = root;
      this.m = model;
      this.opts = opts || {};
      this.N = model.nodes;
      this.E = {};
      model.edges.forEach(e => this.E[e.id] = e);
      this.scenes = {};
      model.scenes.forEach(s => this.scenes[s.id] = s);
      this.where = model.where || {};
      this.state = { view: "hierarchy", scene: "h:root", selected: null, full: false, variant: false, group: null, tab: "overview" };
      this.vp = { x: 0, y: 0, k: 1 };
      this.buildDom();
      this.initTheme();
      this.applyHash(location.hash) || this.show("h:root");
      window.addEventListener("hashchange", () => this.applyHash(location.hash));
      window.addEventListener("resize", () => this.fit());
      window.addEventListener("message", ev => {
        if (ev.data && ev.data.pmTheme) this.setTheme(ev.data.pmTheme, true);
        if (ev.data && ev.data.pmHash) this.applyHash(ev.data.pmHash);
      });
    }

    // ------------------------------------------------------------- DOM
    buildDom() {
      const r = this.root;
      r.classList.add("pm");
      r.innerHTML = "";
      // toolbar
      this.views = el("div", { class: "pm-views" });
      ["hierarchy", "tlm", "classes"].forEach(v => {
        this.views.append(el("button", { "data-view": v, onclick: () => this.switchView(v) }, [VIEW_LABEL[v]]));
      });
      this.crumbs = el("nav", { class: "pm-crumbs" });
      this.search = el("input", { type: "search", placeholder: "Search a component, class, file…  ( / )", list: "pm-search-list", autocomplete: "off" });
      const dl = el("datalist", { id: "pm-search-list" });
      Object.values(this.N).filter(n => n.kind !== "uvm_base").sort((a, b) => a.id.localeCompare(b.id)).forEach(n => {
        dl.append(el("option", { value: n.id }, [n.name !== n.id ? `${n.name} : ${n.type || ""}` : (n.type || "")]));
      });
      this.search.addEventListener("change", () => this.gotoSearch(this.search.value));
      this.search.addEventListener("keydown", e => { if (e.key === "Enter") this.gotoSearch(this.search.value); if (e.key === "Escape") this.search.blur(); });
      this.tools = el("div", { class: "pm-tools" });
      this.btnUp = el("button", { title: "Up one level (Esc)", onclick: () => this.up() }, ["↑ Up"]);
      this.btnMembers = el("button", { title: "Show fields and methods", onclick: () => this.toggleFull() }, ["Members"]);
      this.btnLabels = el("button", { title: "Always show the labels of the arrows (l)", onclick: () => { this.state.labels = !this.state.labels; this.render(); } }, ["Labels"]);
      this.btnVariant = el("button", { title: "Lab 9D variant: analysis FIFOs instead of reference + scoreboard", onclick: () => this.toggleVariant() }, ["Lab 9D"]);
      this.selGroup = el("select", { title: "Class group", onchange: () => this.showGroup(this.selGroup.value) });
      this.selGroup.append(el("option", { value: "" }, ["All classes"]));
      Object.entries(this.m.groups).forEach(([g, meta]) => this.selGroup.append(el("option", { value: g }, [meta.label])));
      const zoom = el("div", { class: "grp" }, [
        el("button", { title: "Fit (f)", onclick: () => this.fit() }, ["Fit"]),
        el("button", { title: "Zoom out (-)", onclick: () => this.zoomBy(0.8) }, ["−"]),
        el("button", { title: "Zoom in (+)", onclick: () => this.zoomBy(1.25) }, ["+"]),
      ]);
      this.menu = el("div", { class: "pm-menu" }, [
        el("button", { onclick: () => this.menu.classList.toggle("open") }, ["Export ▾"]),
        el("ul", {}, [
          el("li", { onclick: () => { this.menu.classList.remove("open"); this.exportSvg(); } }, ["Download SVG (this view)"]),
          el("li", { onclick: () => { this.menu.classList.remove("open"); this.exportPng(); } }, ["Download PNG (2×)"]),
          el("li", { onclick: () => { this.menu.classList.remove("open"); window.print(); } }, ["Print / save as PDF"]),
          el("li", { onclick: () => { this.menu.classList.remove("open"); this.copyLink(); } }, ["Copy link to this view"]),
        ]),
      ]);
      document.addEventListener("click", e => { if (!this.menu.contains(e.target)) this.menu.classList.remove("open"); });
      this.btnTheme = el("button", { title: "Toggle light / dark", onclick: () => this.toggleTheme() }, ["◐"]);
      this.btnPanel = el("button", { title: "Show / hide the panel", onclick: () => { r.classList.toggle("panel-hidden"); this.fit(); } }, ["Panel"]);
      const btnHelp = el("button", { title: "Keyboard shortcuts (?)", onclick: () => this.help.classList.toggle("open") }, ["?"]);
      this.tools.append(this.btnUp, this.btnMembers, this.btnVariant, this.selGroup, this.btnLabels, zoom, this.menu, this.btnTheme, this.btnPanel, btnHelp);
      if (this.opts.standaloneUrl) {
        this.tools.append(el("a", { href: this.opts.standaloneUrl, download: "", title: "Save this map as one HTML file that works offline" }, [el("button", {}, ["Download offline copy"])]));
      }
      r.append(el("header", { class: "pm-toolbar" }, [this.views, this.crumbs, el("div", { class: "pm-search" }, [this.search, dl]), this.tools]));
      // body
      this.svg = svg("svg", { xmlns: SVG_NS });
      const defs = svg("defs");
      defs.innerHTML =
        '<marker id="pm-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z"/></marker>' +
        '<marker id="pm-arrow-rev" viewBox="0 0 10 10" refX="1" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M10,0 L0,5 L10,10 z"/></marker>' +
        '<marker id="pm-triangle" viewBox="0 0 12 12" refX="11" refY="6" markerWidth="12" markerHeight="12" orient="auto"><path d="M0,0 L12,6 L0,12 z"/></marker>';
      this.svg.append(defs);
      this.viewport = svg("g", { class: "pm-viewport" });
      this.svg.append(this.viewport);
      this.canvas = el("div", { class: "pm-canvas" }, [this.svg]);
      this.legend = el("details", { class: "pm-legend", open: "" });
      this.hint = el("div", { class: "pm-hint" }, ["drag to pan · wheel to zoom · click to inspect · double-click to open"]);
      this.canvas.append(this.legend, this.hint);
      this.panel = el("aside", { class: "pm-panel" });
      this.help = el("div", { class: "pm-help", onclick: e => { if (e.target === this.help) this.help.classList.remove("open"); } }, [
        el("div", { class: "card", html:
          "<h3 style='margin-top:0'>Keyboard</h3><table>" +
          "<tr><td><kbd>1</kbd> <kbd>2</kbd> <kbd>3</kbd></td><td>Hierarchy / TLM / Classes</td></tr>" +
          "<tr><td><kbd>/</kbd></td><td>search</td></tr>" +
          "<tr><td><kbd>Enter</kbd> / double-click</td><td>open the selected component</td></tr>" +
          "<tr><td><kbd>Esc</kbd> / <kbd>Backspace</kbd></td><td>up one level</td></tr>" +
          "<tr><td><kbd>←</kbd> <kbd>→</kbd></td><td>select the previous / next item</td></tr>" +
          "<tr><td><kbd>f</kbd> <kbd>+</kbd> <kbd>−</kbd></td><td>fit / zoom</td></tr>" +
          "<tr><td><kbd>m</kbd></td><td>members on / off (Classes)</td></tr>" +
          "<tr><td><kbd>p</kbd></td><td>panel on / off</td></tr></table>" +
          "<p style='color:var(--pm-muted);font-size:12px'>Generated from the SystemVerilog source with pyslang; descriptions from <code>scripts/project_map/annotations.yaml</code>.</p>" }),
      ]);
      r.append(el("div", { class: "pm-body" }, [this.canvas, this.panel, this.help]));
      this.initPanZoom();
      this.initKeys();
    }

    // ------------------------------------------------------------- theme
    initTheme() {
      const h = new URLSearchParams(location.hash.replace(/^#/, ""));
      const t = h.get("theme") || (this.opts.theme) || null;
      if (t) this.setTheme(t, true);
      else if (window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches) this.setTheme("dark", true);
      else this.setTheme("light", true);
    }
    setTheme(t, silent) {
      this.theme = t === "dark" ? "dark" : "light";
      document.documentElement.setAttribute("data-theme", this.theme);
      if (!silent) this.updateHash();
    }
    toggleTheme() { this.setTheme(this.theme === "dark" ? "light" : "dark"); }

    // ------------------------------------------------------------- navigation
    applyHash(hash) {
      const h = new URLSearchParams((hash || "").replace(/^#/, ""));
      if (![...h.keys()].length) return false;
      const view = h.get("view"), node = h.get("node"), scene = h.get("scene");
      if (h.get("theme")) this.setTheme(h.get("theme"), true);
      if (h.get("members") === "1") this.state.full = true;
      if (h.get("variant") === "1") this.state.variant = true;
      if (scene && this.scenes[scene]) { this.show(scene, { silent: true }); }
      else if (view) {
        if (node) this.gotoNode(node, view, { silent: true });
        else this.switchView(view, { silent: true });
      } else if (node) this.gotoNode(node, null, { silent: true });
      else return false;
      if (node && this.N[node]) this.select(node, { silent: true, noPan: false });
      return true;
    }
    updateHash() {
      if (this._silent) return;
      const p = new URLSearchParams();
      p.set("view", this.state.view);
      p.set("scene", this.state.scene);
      if (this.state.selected) p.set("node", this.state.selected);
      if (this.state.full) p.set("members", "1");
      if (this.state.variant) p.set("variant", "1");
      const h = "#" + p.toString().replace(/%3A/g, ":").replace(/%5B/g, "[").replace(/%5D/g, "]").replace(/%2F/g, "/");
      if (location.hash !== h) history.replaceState(null, "", h);
      if (window.parent !== window) { try { window.parent.postMessage({ pmHash: h }, "*"); } catch (e) { /* ignore */ } }
    }
    sceneFor(view) {
      if (view === "hierarchy") return this.state.lastHier || "h:root";
      if (view === "tlm") return this.state.variant ? "tlm:lab09d" : "tlm:main";
      const g = this.state.group ? `uml:${this.state.group}` : "uml:all";
      return this.state.full && this.scenes[g + ":full"] ? g + ":full" : g;
    }
    switchView(view, o) {
      this.state.view = view;
      this.show(this.sceneFor(view), o);
    }
    showGroup(g) { this.state.group = g || null; this.show(this.sceneFor("classes")); }
    toggleFull() { this.state.full = !this.state.full; if (this.state.view === "classes") this.show(this.sceneFor("classes")); }
    toggleVariant() {
      this.state.variant = !this.state.variant;
      if (this.state.view === "tlm") this.show(this.sceneFor("tlm"));
      else this.render();
    }
    up() {
      const s = this.scenes[this.state.scene];
      if (s && s.parent) { const prev = s.node; this.show(s.parent); if (prev) this.select(prev); }
      else if (this.state.selected) this.select(null);
    }
    gotoNode(nid, view, o) {
      const n = this.N[nid];
      if (!n) return false;
      let target = null;
      if (n.scope === "cls" || (view === "classes")) {
        const cls = n.scope === "cls" ? nid : n.cls;
        const cn = this.N[cls];
        if (cn) {
          this.state.group = cn.group && this.m.groups[cn.group] ? cn.group : null;
          this.state.view = "classes";
          target = this.sceneFor("classes");
          if (!(this.where[cls] || []).includes(target)) { this.state.group = null; target = this.sceneFor("classes"); }
          nid = cls;
        }
      } else {
        const cands = this.where[nid] || [];
        const pref = view || this.state.view;
        target = cands.find(s => this.scenes[s].view === pref && (pref !== "tlm" || s === this.sceneFor("tlm")))
          || cands.find(s => this.scenes[s].view === "hierarchy") || cands[0];
        if (!target && n.parent) return this.gotoNode(n.parent, view, o) && this.select(nid, o);
        if (target) this.state.view = this.scenes[target].view;
      }
      if (!target) return false;
      this.show(target, o);
      this.select(nid, o);
      return true;
    }
    gotoSearch(q) {
      q = (q || "").trim();
      if (!q) return;
      let nid = this.N[q] ? q : null;
      if (!nid) {
        const lq = q.toLowerCase();
        const hits = Object.values(this.N).filter(n => n.kind !== "uvm_base" && (n.name.toLowerCase() === lq || (n.type || "").toLowerCase() === lq));
        if (!hits.length) hits.push(...Object.values(this.N).filter(n => n.kind !== "uvm_base" && (n.id.toLowerCase().includes(lq) || (n.file || "").toLowerCase().includes(lq))));
        if (hits.length) nid = (hits.find(n => n.scope !== "cls") || hits[0]).id;
      }
      if (nid) { this.gotoNode(nid); this.search.blur(); }
    }

    // ------------------------------------------------------------- scenes
    show(sceneId, o) {
      const s = this.scenes[sceneId];
      if (!s) return;
      this._silent = !!(o && o.silent);
      this.state.scene = sceneId;
      this.state.view = s.view;
      if (s.view === "hierarchy") this.state.lastHier = sceneId;
      if (s.view === "classes") { this.state.full = !!s.full; this.state.group = s.group || null; }
      if (s.view === "tlm") this.state.variant = sceneId.endsWith("lab09d");
      this.state.selected = null;
      this.render();
      this.fit();
      this.renderPanel();
      this.updateHash();
      this._silent = false;
    }
    render() {
      const s = this.scenes[this.state.scene];
      const g = this.viewport;
      g.innerHTML = "";
      // lanes / frames (TLM)
      (s.lanes || []).forEach(l => {
        const lg = svg("g", { class: "pm-lane" });
        lg.append(svg("line", { x1: l.x - 30, y1: 8, x2: l.x - 30, y2: s.h }));
        const t = svg("text", { x: l.x + l.w / 2, y: 22, "text-anchor": "middle" }); t.textContent = l.label; lg.append(t);
        g.append(lg);
      });
      (s.frames || []).forEach(f => {
        const fg = svg("g", { class: "pm-frame", style: `--kc: var(--k-${f.kind})` });
        fg.append(svg("rect", { x: f.x, y: f.y, width: f.w, height: f.h }));
        const t = svg("text", { x: f.x + 8, y: f.y + 15 }); t.textContent = f.label; fg.append(t);
        g.append(fg);
      });
      // items sorted: containers (shallow first) under leaves
      const items = [...s.items].sort((a, b) => (a.depth - b.depth) || (b.container - a.container));
      items.forEach(it => g.append(this.drawItem(it, s)));
      (s.stubs || []).forEach(st => g.append(this.drawItem(st, s)));
      // edges on top; in dense scenes labels appear only on hover / selection
      this.denseLabels = !this.state.labels && s.edges.length > 14;
      s.edges.forEach(e => g.append(this.drawEdge(e)));
      this.btnLabels.classList.toggle("on", !!this.state.labels);
      this.renderCrumbs(s);
      this.renderLegend(s);
      this.views.querySelectorAll("button").forEach(b => b.classList.toggle("on", b.dataset.view === s.view));
      this.btnUp.disabled = !s.parent;
      this.btnMembers.style.display = s.view === "classes" ? "" : "none";
      this.btnMembers.classList.toggle("on", !!this.state.full);
      this.selGroup.style.display = s.view === "classes" ? "" : "none";
      this.selGroup.value = this.state.group || "";
      this.btnVariant.style.display = s.view === "tlm" ? "" : "none";
      this.btnVariant.classList.toggle("on", !!this.state.variant);
      this.hint.textContent = s.view === "hierarchy" ? "drag to pan · wheel to zoom · click to inspect · double-click a box to open it"
        : s.view === "tlm" ? "click a port or an arrow to highlight the whole path" : "click a class · Members shows fields and methods";
    }
    drawItem(it, s) {
      const n = this.N[it.id] || {};
      const kind = it.kind || n.kind || "object";
      const grp = svg("g", { class: `pm-node ${kind}` + (it.container ? " container" : "") + (it.stub ? " stub" : ""), "data-id": it.id, style: `--kc: var(--k-${kind})` });
      grp.setAttribute("transform", `translate(${it.x},${it.y})`);
      const r = 6;
      grp.append(svg("rect", { class: "box", width: it.w, height: it.h, rx: r }));
      if (it.container) {
        grp.append(svg("rect", { class: "title", width: it.w, height: 30, rx: r }));
        grp.append(svg("rect", { class: "title", y: 24, width: it.w, height: 6 }));
        const t = svg("text", { class: "label", x: 10, y: 20 }); t.textContent = it.label; grp.append(t);
        if (it.sub) { const st = svg("text", { class: "sub", x: 14 + it.label.length * 8.2, y: 20 }); st.textContent = ": " + it.sub; grp.append(st); }
      } else if (s.view === "classes") {
        grp.append(svg("rect", { class: "stripe", width: it.w, height: 4, rx: 2 }));
        const t = svg("text", { class: "label", x: it.w / 2, y: 22, "text-anchor": "middle" }); t.textContent = it.label; grp.append(t);
        const k = svg("text", { class: "kind", x: it.w / 2, y: 36, "text-anchor": "middle" }); k.textContent = it.sub || ""; grp.append(k);
        if (it.full && (it.fields || it.methods)) {
          let y = 44;
          grp.append(svg("line", { class: "sep", x1: 0, y1: y, x2: it.w, y2: y }));
          y += 4;
          (it.fields || []).forEach(f => { y += 16; const m = svg("text", { class: "member", x: 8, y: y - 4 }); m.textContent = f; grp.append(m); });
          if (it.fields && it.fields.length) { y += 4; grp.append(svg("line", { class: "sep", x1: 0, y1: y, x2: it.w, y2: y })); y += 4; }
          (it.methods || []).forEach(f => { y += 16; const m = svg("text", { class: "member", x: 8, y: y - 4 }); m.textContent = f; grp.append(m); });
        }
      } else {
        grp.append(svg("rect", { class: "stripe", width: 5, height: it.h, rx: 2 }));
        const t = svg("text", { class: "label", x: 14, y: 19 }); t.textContent = it.label; grp.append(t);
        if (it.sub) { const st = svg("text", { class: "sub", x: 14, y: 33 }); st.textContent = it.sub; grp.append(st); }
        if (it.children && !it.container && !it.stub) {
          const more = svg("text", { class: "more", x: it.w - 8, y: it.h - 7, "text-anchor": "end" });
          more.textContent = "▸ open";
          const tt = svg("title"); tt.textContent = "open this component"; more.append(tt);
          more.style.pointerEvents = "all";
          more.addEventListener("click", ev => { ev.stopPropagation(); this.open(it.id, it); });
          grp.append(more);
        }
        if (it.stub) {
          const more = svg("text", { class: "more", x: it.w - 8, y: 15, "text-anchor": "end" }); more.textContent = "↗"; grp.append(more);
        }
      }
      (it.ports || []).forEach(p => {
        const pg = svg("g", { class: `pm-port ${p.kind}`, "data-id": p.id, style: `--kc: var(--k-${p.kind})` });
        pg.append(svg("circle", { cx: p.x - it.x, cy: p.y - it.y, r: 5 }));
        const t = svg("text", { x: p.side === "left" ? p.x - it.x + 10 : p.x - it.x - 10, y: p.y - it.y + 4, "text-anchor": p.side === "left" ? "start" : "end" });
        t.textContent = p.label; pg.append(t);
        pg.addEventListener("click", ev => { ev.stopPropagation(); this.select(p.id); });
        pg.addEventListener("mouseenter", () => this.hover(p.id, true));
        pg.addEventListener("mouseleave", () => this.hover(p.id, false));
        grp.append(pg);
      });
      grp.addEventListener("click", ev => { ev.stopPropagation(); if (it.stub) this.open(it.id, it); else this.select(it.id); });
      grp.addEventListener("dblclick", ev => { ev.stopPropagation(); this.open(it.id, it); });
      grp.addEventListener("mouseenter", () => this.hover(it.id, true));
      grp.addEventListener("mouseleave", () => this.hover(it.id, false));
      return grp;
    }
    drawEdge(e) {
      const g = svg("g", { class: `pm-edge kind-${e.kind}` + (e.dashed ? " dashed" : "") + (e.bidir ? " bidir" : ""), "data-id": e.id, "data-from": e.from, "data-to": e.to });
      const pts = e.points;
      let d;
      if (pts.length === 4 && !e.poly) d = `M${pts[0]} C${pts[1]} ${pts[2]} ${pts[3]}`;
      else d = "M" + pts.map(p => p.join(",")).join(" L");
      g.append(svg("path", { class: "hit", d }));
      g.append(svg("path", { class: "line", d }));
      if (e.label) {
        const t = svg("text", { x: e.lx, y: e.ly - 5, "text-anchor": "middle" });
        t.textContent = trunc(e.label, 48); g.append(t);
      }
      if (this.denseLabels) g.classList.add("quiet");
      g.addEventListener("click", ev => { ev.stopPropagation(); this.select(e.id); });
      g.addEventListener("mouseenter", () => this.hoverEdge(e.id, true));
      g.addEventListener("mouseleave", () => this.hoverEdge(e.id, false));
      return g;
    }
    open(nid, it) {
      if (it && it.stub) { if (it.scene && this.scenes[it.scene]) { this.show(it.scene); this.select(nid); } return; }
      const n = this.N[nid];
      if (!n) return;
      if (this.scenes[`h:${nid}`]) { this.show(`h:${nid}`); return; }
      if (n.scope === "cls") { this.gotoNode(nid); return; }
      if (n.cls && this.N[n.cls]) { this.gotoNode(n.cls, "classes"); }
    }
    renderCrumbs(s) {
      this.crumbs.innerHTML = "";
      const chain = [];
      let cur = s;
      while (cur) { chain.unshift(cur); cur = cur.parent ? this.scenes[cur.parent] : null; }
      if (s.view !== "hierarchy") { chain.length = 0; chain.push(s); }
      chain.forEach((c, i) => {
        if (i) this.crumbs.append(el("span", { class: "sep" }, ["›"]));
        const label = c.id === "h:root" ? "Overview" : (c.node ? (this.N[c.node].name) : c.title);
        if (i === chain.length - 1) this.crumbs.append(el("span", { class: "cur" }, [label]));
        else this.crumbs.append(el("a", { onclick: () => this.show(c.id) }, [label]));
      });
    }
    renderLegend(s) {
      const kinds = new Set();
      s.items.forEach(it => { kinds.add(it.kind); (it.ports || []).forEach(p => kinds.add(p.kind)); });
      (s.stubs || []).forEach(it => kinds.add(it.kind));
      this.legend.innerHTML = "";
      this.legend.append(el("summary", {}, ["Legend"]));
      const box = el("div", { class: "items" });
      [...kinds].filter(k => this.m.kinds[k]).sort().forEach(k => {
        box.append(el("span", {}, [el("i", { style: `background: var(--k-${k})` }), this.m.kinds[k].label]));
      });
      this.legend.append(box);
    }

    // ------------------------------------------------------------- selection
    select(id, o) {
      this.state.selected = id || null;
      this.viewport.querySelectorAll(".selected, .dim, .path").forEach(x => x.classList.remove("selected", "dim", "path"));
      if (id) {
        const isEdge = !!this.E[id] || !this.N[id];
        if (isEdge) {
          this.highlightPath(id);
        } else {
          this.viewport.querySelectorAll(`[data-id="${CSS.escape(id)}"]`).forEach(x => x.classList.add("selected"));
          // dim unrelated edges when a port or a component with ports is selected
          const n = this.N[id];
          if (n && (n.port || (n.edges && n.edges.length))) {
            const mine = new Set(this.incidentEdges(id));
            if (mine.size) {
              this.viewport.querySelectorAll(".pm-edge").forEach(g => g.classList.toggle("dim", !mine.has(g.dataset.id)));
              mine.forEach(eid => this.viewport.querySelectorAll(`.pm-edge[data-id="${CSS.escape(eid)}"]`).forEach(g => g.classList.add("path")));
            }
          }
          if (!(o && o.noPan === false) && !(o && o.silent)) this.ensureVisible(id);
        }
      }
      this.renderPanel();
      if (!(o && o.silent)) this.updateHash();
    }
    incidentEdges(nid) {
      // edges touching the node or any of its ports / descendants shown in this scene
      const ids = [];
      const n = this.N[nid];
      const set = new Set([nid, ...(n && n.children ? n.children : [])]);
      this.scenes[this.state.scene].edges.forEach(e => { if (set.has(e.from) || set.has(e.to)) ids.push(e.id); });
      return ids;
    }
    highlightPath(eid) {
      const base = eid.replace(/b$/, "");
      const paths = (this.m.paths || []).filter(p => p.edges.includes(base));
      const set = new Set([eid, base]);
      paths.forEach(p => p.edges.forEach(x => set.add(x)));
      this.viewport.querySelectorAll(".pm-edge").forEach(g => {
        const on = set.has(g.dataset.id);
        g.classList.toggle("path", on);
        g.classList.toggle("dim", !on);
      });
      this.viewport.querySelectorAll(`.pm-edge[data-id="${CSS.escape(eid)}"]`).forEach(g => g.classList.add("selected"));
    }
    hover(id, on) {
      this.viewport.querySelectorAll(`[data-id="${CSS.escape(id)}"]`).forEach(x => x.classList.toggle("hover", on));
      const set = new Set([id, ...((this.N[id] && this.N[id].children) || [])]);
      this.viewport.querySelectorAll(".pm-edge").forEach(g => { if (set.has(g.dataset.from) || set.has(g.dataset.to)) g.classList.toggle("hover", on); });
    }
    hoverEdge(eid, on) {
      this.viewport.querySelectorAll(`.pm-edge[data-id="${CSS.escape(eid)}"]`).forEach(g => g.classList.toggle("hover", on));
      const e = this.sceneEdge(eid);
      if (e) [e.from, e.to].forEach(id => this.viewport.querySelectorAll(`.pm-node[data-id="${CSS.escape(id)}"], .pm-port[data-id="${CSS.escape(id)}"]`).forEach(x => x.classList.toggle("hover", on)));
    }
    sceneEdge(eid) { return this.scenes[this.state.scene].edges.find(e => e.id === eid); }
    siblings() {
      const s = this.scenes[this.state.scene];
      return [...s.items].filter(it => !it.container || s.view !== "hierarchy" || it.depth > 0).sort((a, b) => (a.y - b.y) || (a.x - b.x)).map(it => it.id);
    }

    // ------------------------------------------------------------- pan / zoom
    initPanZoom() {
      const c = this.canvas;
      let drag = null, pinch = null;
      const pointers = new Map();
      c.addEventListener("pointerdown", e => {
        if (e.button !== 0 && e.pointerType === "mouse") return;
        pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
        if (pointers.size === 2) {
          const [a, b] = [...pointers.values()];
          pinch = { d: Math.hypot(a.x - b.x, a.y - b.y), k: this.vp.k, cx: (a.x + b.x) / 2, cy: (a.y + b.y) / 2, x: this.vp.x, y: this.vp.y };
          drag = null;
        } else {
          drag = { x: e.clientX, y: e.clientY, vx: this.vp.x, vy: this.vp.y, moved: false };
        }
        c.setPointerCapture(e.pointerId);
      });
      c.addEventListener("pointermove", e => {
        if (!pointers.has(e.pointerId)) return;
        pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
        if (pinch && pointers.size === 2) {
          const [a, b] = [...pointers.values()];
          const d = Math.hypot(a.x - b.x, a.y - b.y);
          const k = Math.min(6, Math.max(0.08, pinch.k * d / pinch.d));
          const rect = c.getBoundingClientRect();
          const px = pinch.cx - rect.left, py = pinch.cy - rect.top;
          this.vp.k = k;
          this.vp.x = px - (px - pinch.x) * (k / pinch.k);
          this.vp.y = py - (py - pinch.y) * (k / pinch.k);
          this.applyVp();
        } else if (drag) {
          const dx = e.clientX - drag.x, dy = e.clientY - drag.y;
          if (Math.abs(dx) + Math.abs(dy) > 3) { drag.moved = true; c.classList.add("dragging"); }
          this.vp.x = drag.vx + dx; this.vp.y = drag.vy + dy;
          this.applyVp();
        }
      });
      const end = e => {
        pointers.delete(e.pointerId);
        if (pointers.size < 2) pinch = null;
        if (drag && !drag.moved && e.target === this.svg) this.select(null);
        drag = null;
        c.classList.remove("dragging");
      };
      c.addEventListener("pointerup", end);
      c.addEventListener("pointercancel", end);
      c.addEventListener("wheel", e => {
        e.preventDefault();
        const rect = c.getBoundingClientRect();
        const px = e.clientX - rect.left, py = e.clientY - rect.top;
        const f = Math.exp(-e.deltaY * (e.deltaMode === 1 ? 0.05 : 0.0015));
        this.zoomAt(f, px, py);
      }, { passive: false });
      c.addEventListener("dblclick", e => { if (e.target === this.svg) this.fit(); });
    }
    applyVp() { this.viewport.setAttribute("transform", `translate(${this.vp.x},${this.vp.y}) scale(${this.vp.k})`); }
    zoomAt(f, px, py) {
      const k = Math.min(6, Math.max(0.08, this.vp.k * f));
      const real = k / this.vp.k;
      this.vp.x = px - (px - this.vp.x) * real;
      this.vp.y = py - (py - this.vp.y) * real;
      this.vp.k = k;
      this.applyVp();
    }
    zoomBy(f) { const r = this.canvas.getBoundingClientRect(); this.zoomAt(f, r.width / 2, r.height / 2); }
    fit() {
      const s = this.scenes[this.state.scene];
      if (!s) return;
      const r = this.canvas.getBoundingClientRect();
      if (!r.width || !r.height) return;
      const k = Math.min((r.width - 40) / s.w, (r.height - 60) / s.h, 1.6);
      this.vp.k = k;
      this.vp.x = (r.width - s.w * k) / 2;
      this.vp.y = Math.max(20, (r.height - s.h * k) / 2 - 10);
      this.applyVp();
    }
    ensureVisible(id) {
      const s = this.scenes[this.state.scene];
      const it = s.items.find(i => i.id === id) || (s.stubs || []).find(i => i.id === id);
      if (!it) return;
      const r = this.canvas.getBoundingClientRect();
      const x = this.vp.x + (it.x + it.w / 2) * this.vp.k, y = this.vp.y + (it.y + it.h / 2) * this.vp.k;
      if (x < 20 || x > r.width - 20 || y < 20 || y > r.height - 20) {
        this.vp.x = r.width / 2 - (it.x + it.w / 2) * this.vp.k;
        this.vp.y = r.height / 2 - (it.y + it.h / 2) * this.vp.k;
        this.applyVp();
      }
    }

    // ------------------------------------------------------------- keys
    initKeys() {
      document.addEventListener("keydown", e => {
        if (e.target && (e.target.tagName === "INPUT" || e.target.tagName === "SELECT" || e.target.tagName === "TEXTAREA")) return;
        if (e.ctrlKey || e.metaKey || e.altKey) return;
        const k = e.key;
        if (k === "/") { e.preventDefault(); this.search.focus(); this.search.select(); }
        else if (k === "1") this.switchView("hierarchy");
        else if (k === "2") this.switchView("tlm");
        else if (k === "3") this.switchView("classes");
        else if (k === "Escape" || k === "Backspace") { e.preventDefault(); if (this.help.classList.contains("open")) this.help.classList.remove("open"); else this.up(); }
        else if (k === "f") this.fit();
        else if (k === "+" || k === "=") this.zoomBy(1.25);
        else if (k === "-") this.zoomBy(0.8);
        else if (k === "m") this.toggleFull();
        else if (k === "l") { this.state.labels = !this.state.labels; this.render(); }
        else if (k === "p") { this.root.classList.toggle("panel-hidden"); this.fit(); }
        else if (k === "?") this.help.classList.toggle("open");
        else if (k === "Enter") { if (this.state.selected && this.N[this.state.selected]) this.open(this.state.selected); }
        else if (k === "ArrowRight" || k === "ArrowLeft" || k === "ArrowDown" || k === "ArrowUp") {
          e.preventDefault();
          const sib = this.siblings();
          if (!sib.length) return;
          let i = sib.indexOf(this.state.selected);
          i = (k === "ArrowRight" || k === "ArrowDown") ? (i + 1) % sib.length : (i - 1 + sib.length) % sib.length;
          this.select(sib[i]);
        }
      });
    }

    // ------------------------------------------------------------- panel
    renderPanel() {
      const p = this.panel;
      p.innerHTML = "";
      const id = this.state.selected;
      if (!id) { this.renderScenePanel(); return; }
      if (this.E[id] || !this.N[id]) { this.renderEdgePanel(id); return; }
      const n = this.N[id];
      const head = el("div", { class: "pm-panel-head" });
      head.append(el("span", { class: "pm-badge", style: `--kc: var(--k-${n.kind})` }, [n.kind_label || n.kind]));
      if (n.lab) head.append(" ", el("span", { class: "lab", style: "margin-left:6px;font-size:11px" }, [`Lab ${n.lab}`]));
      head.append(el("h2", {}, [n.name]));
      if (n.scope === "cls") head.append(el("div", { class: "path" }, [n.file ? `${n.file}:${n.line}` : ""]));
      else head.append(el("div", { class: "path" }, [n.scope === "tb" && n.id !== "uvm_test_top" ? `uvm_test_top.${n.id}` : n.id, n.type && n.type !== n.name ? `  :  ${n.type}` : ""]));
      // quick navigation
      const acts = el("div", { class: "pm-actions" });
      if (this.scenes[`h:${n.id}`]) acts.append(el("button", { onclick: () => this.show(`h:${n.id}`) }, ["▸ Open"]));
      const sc = this.scenes[this.state.scene];
      if (sc && sc.parent) acts.append(el("button", { onclick: () => this.up() }, ["↑ Up"]));
      if (n.scope !== "cls" && n.cls && this.N[n.cls]) acts.append(el("button", { onclick: () => this.gotoNode(n.cls, "classes") }, ["Class ⇄"]));
      if (n.scope === "cls") {
        const inst = Object.values(this.N).find(x => x.cls === n.id);
        if (inst) acts.append(el("button", { onclick: () => this.gotoNode(inst.id, "hierarchy") }, ["Instance ⇄"]));
      }
      if ((this.where[n.id] || []).some(sid => this.scenes[sid].view === "tlm") && this.state.view !== "tlm") acts.append(el("button", { onclick: () => this.gotoNode(n.id, "tlm") }, ["TLM"]));
      if ((n.code || (n.cls && this.N[n.cls] && this.N[n.cls].code)) && this.state.tab !== "code") acts.append(el("button", { onclick: () => { this.state.tab = "code"; this.renderPanel(); } }, ["</> Code"]));
      if (acts.children.length) head.append(acts);
      p.append(head);
      const tabs = el("div", { class: "pm-tabs" });
      [["overview", "Overview"], ["code", "Code"], ["links", "Links"]].forEach(([t, l]) => {
        tabs.append(el("button", { class: this.state.tab === t ? "on" : "", onclick: () => { this.state.tab = t; this.renderPanel(); } }, [l]));
      });
      p.append(tabs);
      const body = el("div", { class: "pm-panel-body" });
      p.append(body);
      if (this.state.tab === "code") this.renderCode(body, n);
      else if (this.state.tab === "links") this.renderLinks(body, n);
      else this.renderOverview(body, n);
    }
    nodeLink(id, text) {
      const n = this.N[id];
      if (!n) return el("code", {}, [text || id]);
      return el("a", { class: "node", onclick: () => this.gotoNode(id) }, [text || (n.scope === "cls" ? n.name : n.id)]);
    }
    renderOverview(body, n) {
      const add = (h) => body.insertAdjacentHTML("beforeend", h);
      if (n.summary) add(`<p><b>${esc(n.summary)}</b></p>`);
      if (n.note) add(`<div class="note">${esc(n.note)}</div>`);
      if (n.variant) add(`<div class="note">Variant: exists only in <code>${esc(n.variant)}</code>.</div>`);
      if (n.description) add(md(n.description));
      if (n.kind === "uvm_base") add(`<p class="empty">Part of the UVM library.</p>`);
      // type / class
      const facts = el("table");
      const row = (k, v) => { const tr = el("tr"); tr.append(el("th", {}, [k]), el("td", {}, Array.isArray(v) ? v : [v])); facts.append(tr); };
      if (n.scope !== "cls" && n.cls && this.N[n.cls]) row("class", [this.nodeLink(n.cls, n.type)]);
      else if (n.type && n.type !== n.name && n.scope !== "cls") row("type", el("code", {}, [n.type]));
      if (n.base) row("extends", n.base_full ? el("code", {}, [n.base_full.replace(/,\s*uvm_pkg::\w+::\w+/g, "")]) : el("code", {}, [n.base]));
      if (n.chain && n.chain.length) row("base chain", el("code", {}, [n.chain.join(" → ")]));
      if (n.item_type) row("item type", [this.nodeLink(`cls:${n.item_type}`, n.item_type)]);
      if (n.parent && this.N[n.parent]) row("parent", [this.nodeLink(n.parent)]);
      if (n.lab) { const lk = (n.docs || []).find(d => d.title.startsWith("Lab")); row("introduced", lk ? el("a", { href: this.docUrl(lk.url), target: "_top" }, [`Lab ${n.lab}`]) : `Lab ${n.lab}`); }
      if (n.file && n.scope !== "cls") row("source", el("code", {}, [`${n.file}:${n.line}`]));
      if (facts.children.length) { add("<h3>Facts</h3>"); body.append(facts); }
      if (n.alternatives && n.alternatives.length) {
        add("<h3>Other tests (+UVM_TESTNAME)</h3>");
        const ul = el("ul"); n.alternatives.forEach(t => ul.append(el("li", {}, [this.nodeLink(`cls:${t}`, t), " — ", el("span", { style: "color:var(--pm-muted)" }, [this.N[`cls:${t}`] ? this.N[`cls:${t}`].summary : ""])]))); body.append(ul);
      }
      if (n.values) { add("<h3>Values</h3>"); add(`<p><code>${n.values.map(esc).join("</code> <code>")}</code></p>`); }
      // children
      const kids = (n.children || []).filter(c => !this.N[c].port);
      const ports = (n.children || []).filter(c => this.N[c].port);
      if (kids.length) { add("<h3>Children</h3>"); const ul = el("ul"); kids.forEach(c => ul.append(el("li", {}, [this.nodeLink(c, this.N[c].name), " ", el("span", { class: "role" }, [this.N[c].kind_label])]))); body.append(ul); }
      if (ports.length) {
        add("<h3>TLM ports and connections</h3>");
        const ul = el("ul");
        ports.forEach(c => {
          const li = el("li", {}, [this.nodeLink(c, this.N[c].name), " ", el("span", { class: "role" }, [this.N[c].kind_label])]);
          this.connectionsOf(c).forEach(x => li.append(el("div", { style: "font-size:12px;color:var(--pm-muted)" }, [x.dir, " ", this.nodeLink(x.other), x.label ? ` (${x.label})` : ""])));
          ul.append(li);
        });
        body.append(ul);
      }
      if (n.port) {
        add("<h3>Connections</h3>");
        const cs = this.connectionsOf(n.id);
        if (!cs.length) add('<p class="empty">Not connected (in this configuration).</p>');
        const ul = el("ul"); cs.forEach(x => ul.append(el("li", {}, [x.dir, " ", this.nodeLink(x.other), x.label ? ` (${x.label})` : "", x.src ? el("div", { style: "font-size:11px;color:var(--pm-muted)" }, [x.src]) : ""]))); body.append(ul);
        if (n.implicit) add('<p class="empty">Inherited from the UVM base class (not declared in the source).</p>');
      }
      // other edges (vif, handle, reg, flow)
      const others = (n.edges || []).map(id => this.E[id]).filter(e => e && !["connect", "seq_item", "get", "inherits", "port"].includes(e.kind) || (e && e.kind === "port"));
      if (others.length) {
        add("<h3>Relations</h3>");
        const ul = el("ul");
        others.forEach(e => {
          const otherId = e.from === n.id ? e.to : e.from;
          ul.append(el("li", {}, [el("span", { class: "role" }, [e.kind.replace("_", " ")]), " ", e.from === n.id ? "→ " : "← ", this.nodeLink(otherId), e.label ? el("div", { style: "font-size:12px;color:var(--pm-muted)" }, [e.label]) : ""]));
        });
        body.append(ul);
      }
      // fields / methods / constraints
      const fields = (n.fields || []).filter(f => f.role !== "port" || n.scope === "cls");
      if (fields.length) {
        add("<h3>Fields</h3>");
        const t = el("table"); t.innerHTML = "<tr><th>name</th><th>type</th><th>role</th></tr>";
        fields.forEach(f => { const tr = el("tr"); tr.innerHTML = `<td><code>${esc(f.name)}</code></td><td><code>${esc((f.rand ? "rand " : "") + f.type)}</code></td><td class="role">${esc(f.role)}</td>`; t.append(tr); });
        body.append(t);
      }
      if (n.methods && n.methods.length) {
        add("<h3>Methods</h3>");
        add("<p>" + n.methods.map(m => `<code>${esc(m.name)}()</code><span class="role"> ${m.kind}${m.virtual ? " virtual" : ""}</span>`).join(" · ") + "</p>");
      }
      if (n.constraints && n.constraints.length) {
        add("<h3>Constraints</h3>");
        n.constraints.forEach(c => add(`<pre class="constraint">${esc(c.text || c.name)}</pre>`));
      }
      if (n.config_sets && n.config_sets.length) {
        add("<h3>Configuration (uvm_config_db)</h3>");
        const ul = el("ul"); n.config_sets.forEach(s => ul.append(el("li", {}, [el("code", {}, [`${s.inst}  ${s.field} = ${s.value.replace("::get_type()", "")}`])]))); body.append(ul);
      }
      if (n.overrides && n.overrides.length) {
        add("<h3>Factory overrides</h3>");
        const ul = el("ul"); n.overrides.forEach(o => ul.append(el("li", {}, [el("code", {}, [`${o.kind}(${o.args.join(", ")})`])]))); body.append(ul);
      }
      // hardware: ports / signals / tasks
      if (n.ports && n.ports.length && n.scope === "hw") {
        add("<h3>Ports</h3>");
        const t = el("table"); n.ports.forEach(pp => { const tr = el("tr"); tr.innerHTML = `<td><code>${esc(pp.name)}</code></td><td class="role">${esc(pp.dir)}</td><td><code>${esc(pp.type)}</code></td>`; t.append(tr); }); body.append(t);
      }
      if (n.signals && n.signals.length) {
        add("<h3>" + (n.kind === "rtl_block" ? "Symbols" : "Signals") + "</h3>");
        const t = el("table"); n.signals.slice(0, 40).forEach(s => { const tr = el("tr"); tr.innerHTML = `<td><code>${esc(s.name)}</code></td><td><code>${esc(s.type || "")}</code></td><td class="role">L${s.line}</td>`; t.append(tr); }); body.append(t);
      }
      if (n.tasks && n.tasks.length) {
        add("<h3>Tasks / functions</h3>");
        add("<p>" + n.tasks.map(t => `<code>${esc(t.name)}(${esc((t.args || []).join(", "))})</code>`).join(" · ") + "</p>");
      }
      // source preview
      const code = n.code || (n.cls && this.N[n.cls] ? this.N[n.cls].code : "");
      const cfile = n.file || (n.cls && this.N[n.cls] ? this.N[n.cls].file : null);
      if (code) {
        add("<h3>Source</h3>");
        const lines = code.split("\n");
        const headLine = n.line || (n.cls && this.N[n.cls] ? this.N[n.cls].line : 1);
        const prev = lines.slice(0, 14).join("\n");
        body.append(el("div", { class: "pm-code-head" }, [el("span", {}, [`${cfile}:${headLine}  (${lines.length} lines)`]),
          el("a", { class: "node", onclick: () => { this.state.tab = "code"; this.renderPanel(); } }, ["show the whole file →"])]));
        const box = el("div", { class: "pm-code preview" });
        const table = el("table");
        highlightSV(prev.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")).split("\n").forEach((l, i) => {
          const tr = el("tr"); tr.append(el("td", { class: "ln" }, [String(headLine + i)]), el("td", { html: l || " " })); table.append(tr);
        });
        if (lines.length > 14) { const tr = el("tr"); tr.append(el("td", { class: "ln" }, ["…"]), el("td", { html: `<span class="c">// ${lines.length - 14} more lines in the Code tab</span>` })); table.append(tr); }
        box.append(table); body.append(box);
      }
      // instances of a class
      if (n.scope === "cls") {
        const inst = Object.values(this.N).filter(x => x.cls === n.id);
        if (inst.length) { add("<h3>Instances</h3>"); const ul = el("ul"); inst.forEach(x => ul.append(el("li", {}, [this.nodeLink(x.id)]))); body.append(ul); }
        const subs = Object.values(this.N).filter(x => x.scope === "cls" && x.base === n.name);
        if (subs.length) { add("<h3>Subclasses</h3>"); const ul = el("ul"); subs.forEach(x => ul.append(el("li", {}, [this.nodeLink(x.id, x.name), " — ", el("span", { style: "color:var(--pm-muted)" }, [x.summary || ""])]))); body.append(ul); }
      }
    }
    connectionsOf(pid) {
      const out = [];
      Object.values(this.E).forEach(e => {
        if (!["connect", "seq_item", "get", "reg_adapter"].includes(e.kind)) return;
        const lbl = [e.label, e.variant ? "Lab 9D variant" : ""].filter(Boolean).join(", ");
        if (e.from === pid) out.push({ dir: "→", other: e.to, label: lbl, src: e.file ? `${e.file}:${e.line}` : "" });
        else if (e.to === pid) out.push({ dir: "←", other: e.from, label: lbl, src: e.file ? `${e.file}:${e.line}` : "" });
      });
      return out;
    }
    renderCode(body, n) {
      const code = n.code || (n.cls && this.N[n.cls] ? this.N[n.cls].code : "");
      const file = n.file || (n.cls && this.N[n.cls] ? this.N[n.cls].file : null);
      const line = n.line || (n.cls && this.N[n.cls] ? this.N[n.cls].line : 1);
      if (!code) { body.innerHTML = '<p class="empty">No source attached to this item.</p>'; return; }
      // escape first, then colour (the regex works on the escaped text; entities contain no SV tokens of interest)
      const html = highlightSV(code.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"));
      const head = el("div", { class: "pm-code-head" });
      head.append(el("span", {}, [`${file}:${line}`]));
      if (this.opts.repoUrl && file) head.append(el("a", { href: `${this.opts.repoUrl}/blob/main/${file}#L${line}`, target: "_blank", rel: "noopener" }, ["open on GitHub ↗"]));
      body.append(head);
      const box = el("div", { class: "pm-code" });
      const table = el("table");
      html.split("\n").forEach((l, i) => {
        const tr = el("tr");
        tr.append(el("td", { class: "ln" }, [String(line + i)]));
        tr.append(el("td", { html: l || " " }));
        table.append(tr);
      });
      box.append(table);
      body.append(box);
    }
    docUrl(u) { return /^https?:/.test(u) ? u : (this.opts.docsBase || "") + u.replace(/\.md$/, "/").replace(/index\/$/, ""); }
    renderLinks(body, n) {
      const add = (h) => body.insertAdjacentHTML("beforeend", h);
      add("<h3>Read more</h3>");
      const ul = el("ul");
      (n.docs || []).forEach(d => ul.append(el("li", {}, [el("a", { href: this.docUrl(d.url), target: "_top" }, [d.title])])));
      if (!(n.docs || []).length) ul.append(el("li", { class: "empty" }, ["—"]));
      body.append(ul);
      add("<h3>In the map</h3>");
      const ul2 = el("ul");
      if (n.scope !== "cls" && n.cls) ul2.append(el("li", {}, [el("a", { class: "node", onclick: () => this.gotoNode(n.cls, "classes") }, [`Class ${n.type} in the UML view`])]));
      if (n.scope === "cls") Object.values(this.N).filter(x => x.cls === n.id).slice(0, 6).forEach(x => ul2.append(el("li", {}, [el("a", { class: "node", onclick: () => this.gotoNode(x.id, "hierarchy") }, [`Instance ${x.id} in the hierarchy`])])));
      if ((this.where[n.id] || []).some(s => this.scenes[s].view === "tlm")) ul2.append(el("li", {}, [el("a", { class: "node", onclick: () => this.gotoNode(n.id, "tlm") }, ["Show in the TLM / data-flow view"])]));
      if (this.scenes[`h:${n.id}`]) ul2.append(el("li", {}, [el("a", { class: "node", onclick: () => this.show(`h:${n.id}`) }, ["Open (drill down)"])]));
      if (n.parent) ul2.append(el("li", {}, ["Parent: ", this.nodeLink(n.parent)]));
      body.append(ul2);
      add("<h3>Link to this item</h3>");
      const link = this.linkFor(n.id);
      add(`<p><code style="word-break:break-all">${esc(link)}</code></p>`);
    }
    linkFor(id) {
      const p = new URLSearchParams(); p.set("view", this.state.view); p.set("node", id);
      const base = (this.opts.pageUrl || location.href.split("#")[0]);
      return base + "#" + p.toString().replace(/%3A/g, ":").replace(/%5B/g, "[").replace(/%5D/g, "]");
    }
    copyLink() {
      const link = this.state.selected ? this.linkFor(this.state.selected) : (this.opts.pageUrl || location.href.split("#")[0]) + location.hash;
      if (navigator.clipboard) navigator.clipboard.writeText(link).then(() => { this.hint.textContent = "link copied"; });
      else prompt("Link", link);
    }
    renderScenePanel() {
      const s = this.scenes[this.state.scene];
      const p = this.panel;
      const head = el("div", { class: "pm-panel-head" }, [el("span", { class: "pm-badge", style: "--kc: var(--pm-accent)" }, [VIEW_LABEL[s.view]]), el("h2", {}, [s.title])]);
      p.append(head);
      const body = el("div", { class: "pm-panel-body" });
      p.append(body);
      const add = (h) => body.insertAdjacentHTML("beforeend", h);
      if (s.view === "hierarchy") {
        if (s.id === "h:root") add(md("The whole testbench on one page. **tb_top** is the UVM side: the test builds **router_tb**, which holds one env per interface UVC, the virtual sequencer, the router module UVC (reference model + scoreboard) and the register model. **hw_top** holds the DUT, the clock generator and the interface instances; dotted lines are the virtual interfaces that connect the two worlds.\n\nDouble-click any box to open it. Click a box for its role, code and links."));
        else if (s.node) { const n = this.N[s.node]; add(`<p><b>${esc(n.summary || "")}</b></p>` + md(n.description)); add('<p class="empty">Click a child for details; ports are the small circles (producers on the right, consumers on the left). Dashed boxes outside the frame are the far ends of connections leaving this level.</p>'); }
      } else if (s.view === "tlm") {
        add(md("Left to right: who controls whom and where the data goes. Sequences run on **sequencers**, items reach the **drivers** through `seq_item_port`, pins reach the DUT through the virtual interfaces, **monitors** publish on analysis ports, the **router module UVC** receives them through exports: the reference model filters, the scoreboard compares.\n\nClick a port or an arrow to light up the complete path. The **Lab 9D** button swaps in the FIFO-based scoreboard."));
      } else {
        add(md("Inheritance per package. Grey dashed boxes are UVM library classes. Dashed arrows: *runs on* (sequence → sequencer), *uses* (sequence → sub-sequence), *starts* (test → default sequence), *overrides* (factory).\n\n**Members** switches the full UML boxes on (fields with `rand`, methods, constraints)."));
      }
      add(`<h3>Items in this view</h3>`);
      const ul = el("ul");
      [...s.items].filter(it => !it.stub).sort((a, b) => (a.depth - b.depth) || a.label.localeCompare(b.label)).slice(0, 60).forEach(it => {
        const n = this.N[it.id]; if (!n) return;
        ul.append(el("li", {}, [this.nodeLink(it.id, it.label), " ", el("span", { class: "role" }, [n.kind_label || n.kind]), n.summary ? el("div", { style: "font-size:12px;color:var(--pm-muted)" }, [trunc(n.summary, 110)]) : ""]));
      });
      body.append(ul);
    }
    renderEdgePanel(eid) {
      const e = this.E[eid.replace(/b$/, "")] || this.sceneEdge(eid);
      const p = this.panel;
      p.append(el("div", { class: "pm-panel-head" }, [el("span", { class: "pm-badge", style: "--kc: var(--pm-edge)" }, [e.kind.replace("_", " ")]), el("h2", {}, [e.label || e.kind])]));
      const body = el("div", { class: "pm-panel-body" });
      p.append(body);
      const t = el("table");
      const row = (k, v) => { const tr = el("tr"); tr.append(el("th", {}, [k]), el("td", {}, Array.isArray(v) ? v : [v])); t.append(tr); };
      row("from", [this.nodeLink(e.from)]);
      row("to", [this.nodeLink(e.to)]);
      if (e.via) row("via", [this.nodeLink(e.via)]);
      if (e.in_class) row("written in", el("code", {}, [e.in_class + (e.file ? ` (${e.file}:${e.line})` : "")]));
      body.append(t);
      const expl = {
        connect: "An analysis connection: `port.connect(export_or_imp)` in a `connect_phase`. `write()` on the port calls `write()` on every imp reached through the chain, synchronously.",
        seq_item: "The driver pulls items from the sequencer: `get_next_item()` blocks until a sequence sends one; `item_done()` completes the handshake.",
        get: "A blocking `get()` from an analysis FIFO: the consumer runs in its own thread (Lab 9D).",
        handle: "A plain handle assignment in the testbench's `connect_phase`: the virtual sequencer does not own these sequencers, it only points at them.",
        reg_adapter: "`default_map.set_sequencer(sequencer, adapter)`: register reads/writes become bus items, executed on the HBUS sequencer.",
        backdoor: "`set_hdl_path_root()`: backdoor peek/poke go straight to the RTL signals under this path.",
        vif: "A virtual interface handle delivered through `uvm_config_db` from `tb_top` (see the `*_vif_config::set` calls).",
        port: "Module port connections in `hw_top`: the DUT's pins are the interface's signals.",
        clock: "Shared clock / reset nets (not drawn in the picture to keep it readable).",
        flow: "Data or control flow inside the RTL.",
        inherits: "`extends`.",
        runs_on: "The sequence's item type matches this sequencer's parameter (or `p_sequencer` is declared).",
        uses: "A sub-sequence declared as a member and started with `uvm_do`.",
        starts: "A `default_sequence` set on this sequencer's `run_phase` through `uvm_config_wrapper`.",
        overrides: "A factory type override installed by the test.",
      };
      body.insertAdjacentHTML("beforeend", md(expl[e.kind] || ""));
      const paths = (this.m.paths || []).filter(pp => pp.edges.includes(e.id));
      if (paths.length) {
        body.insertAdjacentHTML("beforeend", "<h3>Complete path</h3>");
        const ul = el("ul"); paths.forEach(pp => ul.append(el("li", {}, [this.nodeLink(pp.from), " ⇒ ", this.nodeLink(pp.to), el("span", { class: "role" }, [` (${pp.edges.length} hops)`])]))); body.append(ul);
      }
    }

    // ------------------------------------------------------------- export
    exportSvgString() {
      const s = this.scenes[this.state.scene];
      const clone = this.svg.cloneNode(true);
      const vp = clone.querySelector(".pm-viewport");
      vp.setAttribute("transform", "translate(10,10)");
      clone.setAttribute("width", Math.ceil(s.w + 20));
      clone.setAttribute("height", Math.ceil(s.h + 20));
      clone.setAttribute("viewBox", `0 0 ${Math.ceil(s.w + 20)} ${Math.ceil(s.h + 20)}`);
      const bg = svg("rect", { width: "100%", height: "100%", fill: getComputedStyle(this.canvas).backgroundColor || "#fff" });
      clone.insertBefore(bg, clone.firstChild);
      // inline the computed styles (the exported file has no CSS)
      const props = ["fill", "fill-opacity", "stroke", "stroke-width", "stroke-dasharray", "stroke-linejoin", "opacity", "font-family", "font-size", "font-weight", "text-anchor", "paint-order", "letter-spacing", "text-transform"];
      const live = this.svg.querySelectorAll("*"), copy = clone.querySelectorAll("*");
      live.forEach((src, i) => {
        const dst = copy[i]; if (!dst || dst.tagName === "defs" || dst.closest("defs")) return;
        const cs = getComputedStyle(src);
        props.forEach(pr => { const v = cs.getPropertyValue(pr); if (v) dst.style.setProperty(pr, v); });
        if (src.classList.contains("hit")) dst.remove();
      });
      // markers keep their CSS-driven colours
      clone.querySelectorAll("marker path").forEach(mp => { mp.style.fill = getComputedStyle(this.svg.querySelector("#pm-arrow path")).fill; });
      const title = svg("title"); title.textContent = s.title; clone.insertBefore(title, clone.firstChild);
      return '<?xml version="1.0" encoding="UTF-8"?>\n' + new XMLSerializer().serializeToString(clone);
    }
    download(blob, name) {
      const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = name; document.body.append(a); a.click();
      setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
    }
    fileName(ext) { return "yapp_map_" + this.state.scene.replace(/[^\w.-]+/g, "_") + "." + ext; }
    exportSvg() { this.download(new Blob([this.exportSvgString()], { type: "image/svg+xml" }), this.fileName("svg")); }
    exportPng() {
      const s = this.scenes[this.state.scene];
      const str = this.exportSvgString();
      const img = new Image();
      const url = URL.createObjectURL(new Blob([str], { type: "image/svg+xml" }));
      img.onload = () => {
        const c = document.createElement("canvas");
        c.width = Math.ceil((s.w + 20) * 2); c.height = Math.ceil((s.h + 20) * 2);
        const ctx = c.getContext("2d"); ctx.scale(2, 2); ctx.drawImage(img, 0, 0);
        URL.revokeObjectURL(url);
        c.toBlob(b => this.download(b, this.fileName("png")), "image/png");
      };
      img.src = url;
    }
  }

  // ------------------------------------------------------------------ boot
  function boot() {
    const root = document.getElementById("project-map");
    if (!root) return;
    const inline = document.getElementById("pm-model");
    const opts = {
      repoUrl: root.dataset.repo || "", docsBase: root.dataset.docs || "", standaloneUrl: root.dataset.standalone || "",
      pageUrl: root.dataset.page || "", theme: root.dataset.theme || "",
    };
    const start = model => { window.projectMap = new ProjectMap(root, model, opts); window.projectMap.sceneIds = () => model.scenes.map(s => s.id); };
    if (inline) start(JSON.parse(inline.textContent));
    else fetch(root.dataset.model || "model.json").then(r => r.json()).then(start).catch(err => { root.textContent = "Could not load model.json: " + err; });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot); else boot();
})();
